//! 🔢️ A declared unit variant is constructed only after the actual original discriminator has completed bounded matching.
use super::*;
use crate::{retirement::RetireOwned,retained_clone::RetainedCloneClose,owned::{NativeReceiver,NativeAdvanceSelection},OriginalEffectReply,OriginalEffectReplyComplete};
use std::mem::ManuallyDrop;
pub trait NativeUnitVariants:RetireOwned{fn variant_spec()->NativeVariantSpec;fn from_variant_index(index:usize)->Result<Self,ValueError>where Self:Sized;}
pub struct NativeUnitEnumReceiver<I:NativeValueSource+?Sized,T:NativeUnitVariants>{selector:NativeVariantSelector<I>,output:ManuallyDrop<Option<T>>,retirement:RetainedCloneClose,closing:bool}
impl<I:NativeValueSource+?Sized,T:NativeUnitVariants>NativeUnitEnumReceiver<I,T>{pub fn new()->Self{Self{selector:NativeVariantSelector::new(T::variant_spec()),output:ManuallyDrop::new(None),retirement:Default::default(),closing:false}}}
impl<I:NativeValueSource+?Sized,T:NativeUnitVariants>NativeUnitEnumReceiver<I,T>{
 fn close_route<'reply>(&mut self,mut original:Option<&mut crate::OriginalRetirementCloseLoan<'_>>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,recover:bool)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{
  if self.terminal_is_empty(){return Ok(reply.complete(Ok(RetainedCloneStep::Complete(Default::default()))))}
  let g=effect.grant();let d=match self.close_demands(body){Ok(d)=>d,Err(error)=>return Ok(reply.complete(Err(error.into())))};if !retained_clone_grant_admits(g,d){return semio_framework_value_native_receiver_protocol::native_close_denied(reply)}
  if !self.selector.terminal_is_empty(){let reply=reply.progress();let mut nested=effect.nested(child_grant(g,0));let route=original.as_deref_mut().filter(|_|self.selector.requires_original_control());return match(route,recover){(Some(original),false)=>self.selector.close_original_into(original,body,&mut nested,reply),(Some(original),true)=>self.selector.recover_close_original_into(original,body,&mut nested,reply),(None,false)=>self.selector.close_into(body,&mut nested,reply),(None,true)=>self.selector.recover_close_into(body,&mut nested,reply)}}
  if !self.retirement.is_empty(){return match(original.as_deref_mut().filter(|_|self.retirement.requires_original_control()),recover){(Some(original),false)=>self.retirement.step_original_into(original,body,effect,reply),(Some(original),true)=>self.retirement.recover_step_original_into(original,body,effect,reply),(None,false)=>self.retirement.step_into(body,effect,reply),(None,true)=>self.retirement.recover_step_into(body,effect,reply)}}
  if recover{return Err(invalid())}
  semio_framework_value_native_receiver_protocol::native_close_begun(self.retirement.begin_granted(&mut self.output,effect),reply)
 }
}
impl<I:NativeValueSource+?Sized,T:NativeUnitVariants>NativeReceiver<I,T>for NativeUnitEnumReceiver<I,T>{
 fn demands(&self,input:RetainedCloneRef<'_,I>,body:usize,maximum_work_units:u64)->Result<RetirementDemand,ValueError>{if self.closing||self.output.is_some(){return Err(invalid())}self.selector.validate_input(input)?;if self.selector.result().is_some(){Ok(fixed(0))}else{self.selector.demands(input,body,maximum_work_units)}}
 fn select_advance(&self,input:RetainedCloneRef<'_,I>,body:usize,maximum_work_units:u64)->Result<NativeAdvanceSelection,ValueError>{if self.closing||self.output.is_some(){return Err(invalid())}self.selector.validate_input(input)?;if self.selector.result().is_some(){Ok(NativeAdvanceSelection::Local{work:1})}else{self.selector.select_advance(input,body,maximum_work_units)}}
 fn advance_nested(&mut self,input:RetainedCloneRef<'_,I>,control:&mut NativeDecodeControl<'_>,witness:semio_framework_value_control_contract::OriginalSourceTurnWitness<'_>,body:usize,maximum_work_units:u64,g:RetainedCloneGrant)->crate::RetainedWorkPoll<RetainedCloneStep,crate::native_decoding::NativeReceivingFailure>{if self.closing||self.output.is_some()||self.selector.result().is_some(){return crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(invalid().into()),work:0})}self.selector.advance_nested(input,control,witness,body,maximum_work_units,g)}
 fn advance_local<'reply>(&mut self,input:RetainedCloneRef<'_,I>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>{
  let d=self.demands(input,body,effect.maximum_work_units())?;if !retained_clone_grant_admits(effect.grant(),d){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}
  let Some(selected)=self.selector.result()else{return self.selector.advance_local(input,body,effect,reply.progress())};
  if !effect.performed(1)?{return Ok(reply.complete(Err(ValueError::literal(crate::ValueRefusalKind::WorkLimit,"native unit variant action exceeded its original work").into())))}
  Ok(reply.complete(T::from_variant_index(selected.index).map(|value|{*self.output=Some(value);RetainedCloneStep::Complete(receipt(fixed(0)))}).map_err(|error|error.with_retained_progress(receipt(fixed(0))).into())))
 }
 fn advance_pending(&self)->bool{self.selector.advance_pending()}
 fn output_ready(&self)->bool{!self.closing&&self.output.is_some()}
 semio_framework_value_native_receiver_protocol::native_owned_output!(T,invalid);
 semio_framework_value_native_receiver_protocol::native_receiver_close_start!(closing);
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid())}if !self.selector.terminal_is_empty(){return crate::owned::tree::nested(self.selector.close_demands(body)?,0)}self.retirement.next_owner_demands::<T>(self.output.is_some(),&None,body)}
 fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{if !self.closing{return Err(invalid())}if !self.selector.terminal_is_empty(){return self.selector.close_work_demand(body)}self.retirement.next_owner_work::<T>(self.output.is_some(),&None,body)}
 fn close_step<'reply>(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{self.close_route(None,body,effect,reply,false)}
 fn recover_close_step<'reply>(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{self.close_route(None,body,effect,reply,true)}
 fn close_original_step<'reply>(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{self.close_route(Some(original),body,effect,reply,false)}
 fn recover_close_original_step<'reply>(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{self.close_route(Some(original),body,effect,reply,true)}
 fn requires_original_birth(&self)->bool{if !self.selector.terminal_is_empty(){self.selector.requires_original_birth()}else{self.retirement.requires_original_birth()}}
 fn close_original_birth_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->crate::OriginalRetirementPoll{if grant.maximum_items==0||grant.maximum_depth==0{return crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0})}if !self.selector.terminal_is_empty(){self.selector.close_original_birth_step(original,child_grant(grant,0))}else{self.retirement.step_original_birth(original,grant)}}
 fn requires_original_control(&self)->bool{if !self.selector.terminal_is_empty(){self.selector.requires_original_control()}else{self.retirement.requires_original_control()}}
 fn terminal_is_empty(&self)->bool{self.selector.terminal_is_empty()&&self.output.is_none()&&self.retirement.is_empty()}fn native_terminal_release(&self)->Option<semio_framework_value_native_receiver_protocol::RetainedCursorRelease<Self>>{self.terminal_is_empty().then(||unsafe{semio_framework_value_native_receiver_protocol::RetainedCursorRelease::native(|value:&Self|value.terminal_is_empty())})}
}
impl<I:NativeValueSource+?Sized,T:NativeUnitVariants>Drop for NativeUnitEnumReceiver<I,T>{fn drop(&mut self){let empty=self.terminal_is_empty();assert!(std::thread::panicking()||empty,"native unit variant requires funded closure");if empty{unsafe{ManuallyDrop::drop(&mut self.output);}}}}
